            },
            {
              "descriptor": {
                "code": "DELAY_INTEREST"
              },
              "value": "2.5"
            },
            {
              "descriptor": {
                "code": "STATIC_TERMS"
              },
              "value": "https://api.example-bap.com/booking/terms"
            },
            {
              "descriptor": {
                "code": "MANDATORY_ARBITRATION"
              },
              "value": "true"
            },
            {
              "descriptor": {
                "code": "COURT_JURISDICTION"
              },
              "value": "New Delhi"
            },
            {
              "descriptor": {
                "code": "SETTLEMENT_BASIS"
              },
              "value": "Delivery"
            }
          ]
        }
      ]
    return defaultPayload;
  } catch (error) {
    throw new Error(`Failed to generate payload: ${error.message}`);
  }
}

