 * @returns {number} total seconds; 0 when the input is unparseable
 */
function isoDurToSec(duration) {
	const durRE =
		/P((\d+)Y)?((\d+)M)?((\d+)W)?((\d+)D)?T?((\d+)H)?((\d+)M)?((\d+)S)?/;
