		(Number(s?.[4]) || 0) * 2628288 +
		(Number(s?.[6]) || 0) * 604800 +
		(Number(s?.[8]) || 0) * 86400 +
		(Number(s?.[10]) || 0) * 3600 +
		(Number(s?.[12]) || 0) * 60 +
		(Number(s?.[14]) || 0)
	);
