    // =========================
    // Build intent
    // =========================

    defaultPayload.message.intent = {
      ...(defaultPayload.message.intent || {}),
      fulfillment: {
        stops: [
          {
            type: "START",
            location: {
              descriptor: {
                code: startCode,
              },
            },
          },
          {
            type: "END",
            location: {
              descriptor: {
                code: endCode,
              },
            },
          },
        ],

        vehicle: {
          category: "BUS",
        },
      }
    };

    return defaultPayload;
  } catch (error) {
    console.error(
      "Error generating search payload:",
      {
        error: error.message,
        session_id: sessionData?.session_id,
        transaction_id:
          defaultPayload?.context
            ?.transaction_id,
      }
    );

    return defaultPayload;
  }
}

