  const order = (targetPayload.message || {}).order || {};
  // Required fields
  if (!order.provider || !order.provider.id) {
    return { valid: false, code: 30000,
             description: 'select: message.order.provider.id is required' };
  }
  if (!Array.isArray(order.items) || order.items.length === 0) {
    return { valid: false, code: 30000,
             description: 'select: message.order.items must be a non-empty array' };
  }
  for (const item of order.items) {
    if (!item.id) {
      return { valid: false, code: 30000,
               description: 'select: every item must have an id' };
    }
    const qty = item.quantity && item.quantity.selected && item.quantity.selected.count;
    if (qty === undefined || qty === null || Number(qty) < 1) {
      return { valid: false, code: 30000,
               description: 'select: item "' + item.id + '" must have quantity.selected.count >= 1' };
    }
  }
  // Cross-check: selected items must exist in on_search catalog (session key: items)
  if (sessionData && Array.isArray(sessionData.items) && sessionData.items.length > 0) {
    const availableIds = sessionData.items.map(function(i) { return i.id; });
    for (const item of order.items) {
      if (availableIds.indexOf(item.id) === -1) {
        return { valid: false, code: 30000,
                 description: 'select: item "' + item.id + '" was not returned in on_search response' };
      }
    }
  }
  // Cross-check: provider must match on_search provider (session key: provider_id)
  if (sessionData && sessionData.provider_id) {
    if (order.provider.id !== sessionData.provider_id) {
      return { valid: false, code: 30000,
               description: 'select: provider "' + order.provider.id + '" does not match on_search provider "' + sessionData.provider_id + '"' };
    }
  }
  return { valid: true, code: 200, description: 'Valid select payload' };
}

