    const user_input = typeof rawData === "string" ? JSON.parse(rawData) : rawData;
    defaultPayload.context.bpp_id = user_input?.bpp_id ?? "xyz.com";
    defaultPayload.context.bpp_uri = getSubscriberUrl(sessionData, "bpp")
    defaultPayload.context.location.city.code =
        user_input?.city_code ?? "std:011";
    defaultPayload.message.intent.fulfillment = {
        stops: [
            {
                type: "START",
                location: {
                    descriptor: {
                        code: user_input?.start_stop_code ?? "SHAHEED_STHAL",
                    },
                },
            },
            {
                type: "END",
                location: {
                    descriptor: {
                        code: user_input?.end_stop_code ?? "AZADPUR",
                    },
                },
            },
        ],
        vehicle: {
            category: user_input?.vehicle_category ?? "METRO",
        },
    };
    defaultPayload.message.intent.payment.collected_by =
        user_input?.collector ?? "BPP";
    // Preserve the stops as they are - do not modify the codes
    // The codes (e.g., MOCK_STATION_1, MOCK_STATION_15) will be saved via save-data.yaml
    return defaultPayload;
}

async function generate(defaultPayload, sessionData) {
  return search2Generator(defaultPayload, sessionData);
}

function validate(targetPayload, sessionData) {
  // Required fields in search payload
  const requiredPaths = [
    ["context","bpp_id"],
    ["context","location","city","code"],
    ["message","intent","fulfillment","stops"],
    ["message","intent","payment","collected_by"]
  ];
  for (const segs of requiredPaths) {
    let cur = targetPayload;
    for (const s of segs) {
      if (cur == null) { cur = undefined; break; }
      cur = cur[s];
    }
    if (cur === undefined || cur === null) {
      return { valid: false, code: 30000,
               description: 'Required field "' + segs.join('.') + '" missing in search payload' };
    }
  }
  // Fulfillment stops must have START and END
  const stops = ((targetPayload.message || {}).intent || {}).fulfillment
                 && targetPayload.message.intent.fulfillment.stops;
  if (Array.isArray(stops)) {
    const hasStart = stops.some(function(s) { return s.type === 'START'; });
    const hasEnd   = stops.some(function(s) { return s.type === 'END'; });
    if (!hasStart || !hasEnd) {
      return { valid: false, code: 30000,
               description: 'search fulfillment.stops must contain a START stop and an END stop' };
    }
  }
  return { valid: true, code: 200, description: 'Valid search payload' };
}

function meetsRequirements(sessionData) {
  // optional session keys (guarded in generator): collected_by
  const requiredSession = ["search2_fulfillment"];
  const requiredInputs  = [];
  for (const k of requiredSession) {
    if (sessionData == null || sessionData[k] === undefined || sessionData[k] === null) {
      return { valid: false, code: "MISSING_SESSION_DATA",
               description: "Required session key \"" + k + "\" is missing" };
    }
  }
  for (const k of requiredInputs) {
