/**
 * Generate a consent handler from the Finvu AA Service.
 *
 * Reads the service base URL from `sessionData.finvuUrl` — the installing
 * service MUST include that origin in
 *   MockRunner.initSharedRunner({ allowedFetchBaseUrls: [...] })
 * otherwise the sandboxed fetch will be blocked.
 *
 * Times out after 10s via AbortController.
 *
 * @param {Object} sessionData  session data; `sessionData.finvuUrl` is required
 * @param {Object} params
 * @param {string} params.custId                customer ID (required)
 * @param {string} [params.templateName]        defaults to "FINVUDEMO_TESTING"
 * @param {string} [params.consentDescription]  defaults to "Gold Loan Account Aggregator Consent"
 * @param {string} [params.redirectUrl]         defaults to "https://google.co.in"
 * @returns {Promise<string>} the `consentHandler` returned by the AA service
 * @throws {Error} when `custId` or `sessionData.finvuUrl` is missing, on non-OK
 *   response, on missing `consentHandler` in the body, or on 10s timeout
 */
async function generateConsentHandler(
	sessionData,
	{
		custId,
		templateName = "FINVUDEMO_TESTING",
		consentDescription = "Gold Loan Account Aggregator Consent",
		redirectUrl = "https://google.co.in",
	},
) {
	if (!custId) {
		throw new Error("custId is required");
	}
	const baseUrl = sessionData && sessionData.finvuUrl;
	if (!baseUrl) {
		throw new Error("sessionData.finvuUrl is required");
	}

	const url = `${baseUrl}/finvu-aa/consent/generate`;

	const payload = {
		custId,
		templateName,
		consentDescription,
		redirectUrl,
	};

	console.log("Calling Finvu AA Service:", url);
	console.log("Consent request payload:", payload);

	const controller = new AbortController();
	const timeout = setTimeout(() => controller.abort(), 10000);

	try {
		const res = await fetch(url, {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
			},
			body: JSON.stringify(payload),
			signal: controller.signal,
		});

		if (!res.ok) {
			const text = await res.text();
			throw new Error(`Request failed: ${res.status} ${text}`);
		}

		const data = await res.json();

		if (!data || !data.consentHandler) {
			throw new Error("Invalid response: consentHandler missing");
		}

		return data.consentHandler;
	} catch (err) {
		if (err && err.name === "AbortError") {
			throw new Error("Request timed out after 10 seconds");
		}
		throw err;
	} finally {
		clearTimeout(timeout);
	}
}

function toLocalISOStringWithZ(date) {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, "0")
  const day = String(date.getDate()).padStart(2, "0")
  const hours = String(date.getHours()).padStart(2, "0")
  const minutes = String(date.getMinutes()).padStart(2, "0")
  const seconds = String(date.getSeconds()).padStart(2, "0")
  const milliseconds = String(date.getMilliseconds()).padStart(3, "0")

  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}.${milliseconds}Z`
}

// Function to create dynamic route based on start and end location codes
function createDynamicRoute(startCode, endCode) {
  const allStops = exampleFullfillment()[0].stops
  const filteredStops = []
  let startIndex = -1
  let endIndex = -1

  // Find start and end indices by matching the code
  for (let i = 0; i < allStops.length; i++) {
    const stopCode = allStops[i]?.location?.descriptor?.code
    if (stopCode === startCode) {
      startIndex = i
    }
    if (stopCode === endCode) {
      endIndex = i
    }
  }

  // If start or end not found, or start >= end, return ALL stops from fulfillment-generator
  if (startIndex === -1 || endIndex === -1 || startIndex >= endIndex) {
    // Return all stops as-is from the fulfillment-generator
    return allStops.map(stop => JSON.parse(JSON.stringify(stop)))
  }

  // Filter stops between start and end (inclusive)
  // Only change type for first (START) and last (END) stops
  // All intermediate stops keep their original type (INTERMEDIATE_STOP, TRANSIT_STOP, etc.)
  for (let i = startIndex; i <= endIndex; i++) {
    const stop = JSON.parse(JSON.stringify(allStops[i])) // Deep clone

    if (i === startIndex) {
      // First stop becomes START type
      stop.type = "START"
      delete stop.parent_stop_id
      delete stop.instructions
    } else if (i === endIndex) {
      // Last stop becomes END type
      stop.type = "END"
    }
    // All stops in between (i > startIndex && i < endIndex) keep their original type

    // Update parent_stop_id for proper chaining within the filtered range
    if (i > startIndex) {
      stop.parent_stop_id =
        filteredStops[filteredStops.length - 1]?.id || String(i)
    }

    filteredStops.push(stop)
  }

  return filteredStops
}

async function generate(defaultPayload, sessionData) {
  try {
  // Get current date
  const today = new Date()

  // Create start time at 5:30 AM of current date (local time)
  const startTime = new Date(today)
  startTime.setHours(5, 30, 0, 0)

  // Create end time at 11:30 PM of current date (local time)
  const endTime = new Date(today)
  endTime.setHours(23, 30, 0, 0)

  // Get start and end location codes from sessionData.search2_fulfillment.stops
  const search2Stops = sessionData?.search2_fulfillment?.stops || []

  const startStop = search2Stops.find(stop => stop.type === "START")
  const endStop = search2Stops.find(stop => stop.type === "END")

  const startLocationCode = startStop?.location?.descriptor?.code
  const endLocationCode = endStop?.location?.descriptor?.code

  // Create dynamic stops based on start and end codes
  let dynamicStops = []
  if (startLocationCode && endLocationCode) {
    dynamicStops = createDynamicRoute(startLocationCode, endLocationCode)
  }

  // Update fulfillments with dynamic stops
  // Note: fulfillments are inside providers[], not at catalog.fulfillments level
  if (dynamicStops.length > 0) {
    // Update fulfillments inside each provider
    defaultPayload.message.catalog.providers = defaultPayload.message.catalog.providers?.map(
      provider => {
        const updatedFulfillments = provider.fulfillments?.map(fulfillment => {
          if (fulfillment.type === "TRIP") {
            return {
              ...fulfillment,
              stops: dynamicStops
            }
          }
          return fulfillment
        })

        return {
          ...provider,
          fulfillments: updatedFulfillments
        }
      }
    )
  }

  defaultPayload.message.catalog.providers = defaultPayload.message.catalog.providers.map(
    provider => {
      // Get fulfillments from the payload
      const fulfillments =
        defaultPayload.message.catalog.fulfillments ||
        provider.fulfillments ||
        []

      // Process items and update timestamp based on duration
      const updatedItems =
        provider.items?.map(item => {
          // Calculate item price based on fulfillment stops.length * 10
          const itemFulfillmentId = item.fulfillment_ids?.[0]
          const matchingFulfillment = fulfillments.find(
            f => f.id === itemFulfillmentId && f.type === "TRIP"
          )

          let updatedItem = { ...item }
          if (matchingFulfillment && matchingFulfillment.stops) {
            const stopsCount = matchingFulfillment.stops.length
            const itemCode = item.descriptor?.code
            // SJT = stops.length * 10, RJT = stops.length * 20
            const multiplier = itemCode === "RJT" ? 20 : 10
            const calculatedPrice = stopsCount * multiplier
            updatedItem.price = {
              ...item.price,
              value: String(calculatedPrice)
            }
          }

          if (item.time && item.time.duration) {
            // Parse duration (e.g., PT2D = 2 days)
            const durationMatch = item.time.duration.match(/P(\d+)D/)
            if (durationMatch) {
              const days = parseInt(durationMatch[1], 10)
              const futureDate = new Date(today)
              futureDate.setDate(futureDate.getDate() + days)
              return {
                ...updatedItem,
                time: {
                  ...item.time,
                  timestamp: toLocalISOStringWithZ(futureDate)
                }
              }
            }
          }
          return updatedItem
        }) || provider.items

      return {
        ...provider,
        items: updatedItems,
        payments: [{ collected_by: sessionData?.collected_by ?? "BPP" }],
        time: {
          range: {
            start: toLocalISOStringWithZ(startTime),
            end: toLocalISOStringWithZ(endTime)
          }
        }
      }
    }
  )
  return defaultPayload
} catch (err) {
  console.error(err)
}

}

function validate(targetPayload, sessionData) {
  // message.catalog.providers must be a non-empty array
  const catalog = (targetPayload.message || {}).catalog || {};
  const providers = catalog.providers;
  if (!Array.isArray(providers) || providers.length === 0) {
    return { valid: false, code: 30000,
             description: 'on_search: message.catalog.providers must be a non-empty array' };
  }
  for (const provider of providers) {
    if (!provider.id) {
      return { valid: false, code: 30000,
               description: 'on_search: every provider must have an id' };
    }
    // items
    if (!Array.isArray(provider.items) || provider.items.length === 0) {
      return { valid: false, code: 30000,
               description: 'on_search: provider "' + provider.id + '" must have at least one item' };
    }
    for (const item of provider.items) {
      if (!item.id) {
        return { valid: false, code: 30000,
                 description: 'on_search: every item under provider "' + provider.id + '" must have an id' };
      }
    }
    // fulfillments
    const ffs = provider.fulfillments || provider.fulfilments;
    if (!Array.isArray(ffs) || ffs.length === 0) {
      return { valid: false, code: 30000,
               description: 'on_search: provider "' + provider.id + '" must have at least one fulfillment' };
    }
    for (const ff of ffs) {
      if (!ff.id) {
        return { valid: false, code: 30000,
                 description: 'on_search: every fulfillment under provider "' + provider.id + '" must have an id' };
      }
    }
  }
  return { valid: true, code: 200, description: 'Valid on_search payload' };
}

